INSERT INTO `tb_products` VALUES (5,'AMZ-ECHOSHOW21-2024-BLK','Amazon Echo Show 21','Pantalla inteligente Amazon Echo Show 21 de 21.4 pulgadas Full HD 1920x1080, Alexa integrada, Fire TV, cámara de 13 MP, Wi-Fi 6E, Bluetooth 5.0, 4 GB de RAM, almacenamiento interno de 16 GB, sistema de audio con dos woofers de 2 pulgadas y dos tweeters de 0.6 pulgadas. Incluye control remoto por voz Alexa y soporte para montaje en pared. Color negro.',7999.00,12,_binary '','2026-09-22 10:28:19','2026-09-22 10:28:19'),(6,'OAK-OO9415-0142','Oakley Corridor SQ OO9415 Sunglasses Men','Lentes de sol Oakley Corridor SQ modelo OO9415-0142 para hombre, tamaño XL 138 mm, armazón Matte Black fabricado en O Matter, diseño semicontorneado rectangular, micas Prizm Black con transmisión de luz del 11%, almohadilla nasal y patillas de Unobtainium para mayor agarre y tecnología Prizm para mejorar color y contraste.',5059.00,18,_binary '','2026-09-22 10:28:19','2026-09-22 10:28:19'),(7,'PROD-001','Laptop Dell XPS 13','Laptop ultraligera con procesador Intel i7 y 16GB RAM',24999.00,10,_binary '','2026-09-22 10:48:20','2026-09-22 10:48:20'),(8,'PROD-002','Smartphone Samsung S23','Teléfono móvil con cámara de 50MP y pantalla AMOLED',18500.50,15,_binary '','2026-09-22 10:48:20','2026-09-22 10:48:20'),(9,'PROD-003','Audífonos Sony WH-1000XM5','Audífonos inalámbricos con cancelación de ruido activa',6800.00,25,_binary '','2026-09-22 10:48:20','2026-09-22 10:48:20'),(10,'PROD-004','Monitor LG 27 Pulgadas','Monitor Gaming 4K IPS de 144Hz',7499.99,8,_binary '','2026-09-22 10:48:20','2026-09-22 10:48:20'),(11,'PROD-005','Teclado Mecánico Logitech','Teclado RGB con switches táctiles inalámbrico',2200.00,30,_binary '','2026-09-22 10:48:20','2026-09-22 10:48:20'),(12,'RAM-00001-988','NexaMemory Memoria RAM DDR4 8GB 2666MHz 1 módulo RAM0001','Memoria de escritorio DDR4, capacidad total 8 GB, frecuencia 2666 MHz, formato UDIMM, 1 módulo. Marca comercial simulada NexaMemory. Modelo interno RAM0001.',1490.51,97,_binary '','2026-09-22 10:55:58','0000-00-00 00:00:00'),(13,'SSD-00002-466','FlashCore SSD 2TB NVMe M.2 PCIe 4.0 SSD0002','Unidad de estado sólido de 2TB, interfaz NVMe M.2 PCIe 4.0, rendimiento secuencial aproximado de 7000/6000 MB/s. Marca comercial simulada FlashCore. Modelo interno SSD0002.',5970.33,179,_binary '','2026-09-22 10:55:58','0000-00-00 00:00:00'),(14,'HDD-00003-756','DataCore Disco duro 8TB 5400RPM SATA 3.5\" para escritorio HDD0003','Disco duro mecánico de 8TB, formato 3.5 pulgadas, interfaz SATA 6 Gb/s, 5400 RPM, orientado a escritorio. Marca comercial simulada DataCore. Modelo interno HDD0003.',3829.97,73,_binary '','2026-09-22 10:55:58','0000-00-00 00:00:00'),(15,'CPU-00004-292','VectorChip Procesador 6 núcleos 12 hilos AM5 CPU0004','Procesador para escritorio con 6 núcleos y 12 hilos, socket AM5, frecuencia base 4.0 GHz y turbo de hasta 4.8 GHz. Marca comercial simulada VectorChip. Modelo interno CPU0004.',9753.26,108,_binary '','2026-09-22 10:55:58','0000-00-00 00:00:00'),(16,'MB-00005-826','NexaBoard Tarjeta madre AM5 DDR5 Micro-ATX Wi-Fi 6E MB0005','Tarjeta madre formato Micro-ATX, socket AM5, soporte para memoria DDR5, almacenamiento M.2 NVMe y conectividad Wi-Fi 6E. Marca comercial simulada NexaBoard. Modelo interno MB0005.',1792.48,35,_binary '','2026-09-22 10:55:58','0000-00-00 00:00:00'),(17,'GPU-00006-297','PixelForge Tarjeta gráfica 16GB GDDR6 256-bit GPU0006','Tarjeta gráfica dedicada con 16 GB de memoria GDDR6, bus de 256 bits, interfaz PCIe 4.0 x16, salidas HDMI y DisplayPort. Marca comercial simulada PixelForge. Modelo interno GPU0006.',19218.92,49,_binary '','2026-09-22 10:55:58','0000-00-00 00:00:00'),(18,'RTR-00007-926','NetWave Router Wi-Fi 6E AXE5400 Gigabit RTR0007','Router inalámbrico Wi-Fi 6E AXE5400, doble banda, 5 puertos Ethernet Gigabit, WPA2/WPA3 y soporte para red de invitados. Marca comercial simulada NetWave. Modelo interno RTR0007.',2381.55,11,_binary '','2026-09-22 10:55:58','0000-00-00 00:00:00'),(19,'S