/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_categories_after_update` AFTER UPDATE ON `tbc_categories` FOR EACH ROW BEGIN

    DECLARE cambios TEXT DEFAULT '';

    

    IF NOT (OLD.name <=> NEW.name) THEN
        SET cambios = CONCAT(
            cambios,
            'name: [',
            COALESCE(OLD.name, 'NULL'),
            '] -> [',
            COALESCE(NEW.name, 'NULL'),
            ']; '
        );
    END IF;


    

    IF NOT (OLD.description <=> NEW.description) THEN
        SET cambios = CONCAT(
            cambios,
            'description: [',
            COALESCE(OLD.description, 'NULL'),
            '] -> [',
            COALESCE(NEW.description, 'NULL'),
            ']; '
        );
    END IF;


    

    IF NOT (OLD.sup_id_category <=> NEW.sup_id_category) THEN
        SET cambios = CONCAT(
            cambios,
            'sup_id_category: [',
            COALESCE(OLD.sup_id_category, 'NULL'),
            '] -> [',
            COALESCE(NEW.sup_id_category, 'NULL'),
            ']; '
        );
    END IF;


    

    IF NOT (OLD.status <=> NEW.status) THEN
        SET cambios = CONCAT(
            cambios,
            'status: [',
            OLD.status + 0,
            '] -> [',
            NEW.status + 0,
            ']; '
        );
    END IF;


    

    IF cambios <> '' THEN

        INSERT INTO tb_logs (
            table_name,
            table_operation,
            db_user,
            operation_description,
            operation_date,
            operation_status
        )
        VALUES (
            'tbc_categories',
            'Update',
            USER(),

            CONCAT(
                'Categor�a actualizada. ',
                'ID=', NEW.ID,
                ', Cambios: ',
                cambios
            ),

            CURRENT_TIMESTAMP,
            b'1'
        );

    END IF;

END */;;
DELIMITER ;
