/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_products_categories_after_update` AFTER UPDATE ON `tbd_products_categories` FOR EACH ROW BEGIN

    INSERT INTO tb_logs (
        table_name,
        table_operation,
        db_user,
        operation_description,
        operation_date,
        operation_status
    )
    VALUES (
        'tbd_products_categories',
        'Update',
        USER(),
        CONCAT(
            'Relaci�n producto-categor�a actualizada. ',
            'Registro original [category_ID=', OLD.category_ID,
            ', product_ID=', OLD.product_ID,
            ']. Cambios: ',

            CONCAT_WS(
                ', ',

                IF(
                    NOT (OLD.category_ID <=> NEW.category_ID),
                    CONCAT(
                        'category_ID: ',
                        OLD.category_ID,
                        ' -> ',
                        NEW.category_ID
                    ),
                    NULL
                ),

                IF(
                    NOT (OLD.product_ID <=> NEW.product_ID),
                    CONCAT(
                        'product_ID: ',
                        OLD.product_ID,
                        ' -> ',
                        NEW.product_ID
                    ),
                    NULL
                ),

                IF(
                    NOT (OLD.status <=> NEW.status),
                    CONCAT(
                        'status: ',
                        OLD.status + 0,
                        ' -> ',
                        NEW.status + 0
                    ),
                    NULL
                )

            )
        ),
        CURRENT_TIMESTAMP,
        b'1'
    );

END */;;
